SELECT CURRENT_TIMESTAMP() checked_at_utc,c.payment_method,c.service_provider,t.payment_option,COUNT(*) charge_rows,COUNT(DISTINCT c.id) distinct_charges,MIN(DATE(c.payment_date)) first_payment_date,MAX(DATE(c.payment_date)) last_payment_date FROM `pacific-plating-282708.careos.carepay_charges` c LEFT JOIN `pacific-plating-282708.careos.carepay_transactions` t ON t.id=c.transaction_id WHERE c.status='SUCCESSFUL' AND DATE(c.payment_date)>=DATE '2026-01-01' AND DATE(c.payment_date)<DATE '2026-10-01' AND (c.payment_method='EDC' OR c.payment_method='BANK_TRANSFER') GROUP BY c.payment_method,c.service_provider,t.payment_option ORDER BY c.payment_method,distinct_charges DESC;